mapper.select:
SELECT 'place' AS kind, slug, ST_Y(location::geometry) AS latitude, ST_X(location::geometry) AS longitude, name, category, subtype, opening_hours FROM place WHERE status = 'public' AND ST_Intersects(location::geometry, ST_MakeEnvelope(#{west}, #{south}, #{east}, #{north}, 4326))
AND category IN #{category}
ORDER BY id LIMIT #{limit}
